#include "thinkercad/circuit.hpp"
#include <iostream>
using namespace thinkercad;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
int main(){CircuitDocument doc;doc.part("board").model="esp32-c3";Esp8266Board board;board.configure("esp32-c3");board.pinMode(0,PinMode::InputPullup);board.pinMode(1,PinMode::InputPulldown);auto button=doc.addPart(PartKind::Button,400,0);doc.part(button).parameters["bounceUs"]=2000;doc.connect({"board","GPIO0"},{button,"1"});doc.connect({"board","GND"},{button,"2"});TransientSimulation sim;TransientSimulation::Boards boards{{"board",&board}};auto at=[&](Microseconds t){return sim.advance(doc,boards,t).level({"board","GPIO0"});};at(3000);check(at(3100)==Level::High,"Idle pull-up");check(doc.solve(board).level({"board","GPIO1"})==Level::Low,"Pull-down circuit voltage");doc.part(button).pressed=true;at(3100);check(at(3400)==Level::Low,"Bounce contact closes");check(at(3700)==Level::High,"Bounce contact reopens");check(at(5500)==Level::Low,"Held button stays low");doc.part(button).pressed=false;at(5500);check(at(8000)==Level::High,"Released button returns high");sim.reset();std::cout<<"Pull-up/down and deterministic contact bounce passed\n";}
